---
--- title: Recursive factorial
--- description: Recursion with if/else as the base case.
--- expected_output: |
---   720
--- tags: [recursion, control-flow]
---

int factorial(int n) {
    if n <= 1 { return 1; } else { return n * factorial(n - 1); }
}

int main() {
    print_int(factorial(6));
    println();
    return 0;
}

---
--- title: Sum of a range
--- description: Iterate 0..n with for-in, accumulating into a mut int.
--- expected_output: |
---   45
--- tags: [for-in, mutability]
---

int sum_to(int n) {
    mut int total := 0;
    for i in 0..n { total = total + i; }
    return total;
}

int main() {
    print_int(sum_to(10));
    println();
    return 0;
}
